do $release$ declare payload jsonb:='{"batch":"verified-synopses-20261107-test","project":"hlvujbrmfdlrfxdjwsmb","actions":[{"relation":"works","ref":"canonical-library-work","key":{"id":991880009},"before":{"id":991880009,"title":"Almost Transparent Blue","author_id":991900009,"first_publish_year":2003,"open_library_id":"OL7989537W","cover_id":null,"source_type":null,"work_type":null,"native_identity_key":null},"after":{"id":991880009,"title":"Almost Transparent Blue","author_id":991900009,"first_publish_year":2003,"open_library_id":"OL3741471W","cover_id":null,"source_type":null,"work_type":null,"native_identity_key":null}},{"relation":"catalog_work_descriptions","ref":"summary-2093","key":{"work_id":991880002,"language":"en"},"before":null,"after":{"work_id":991880002,"language":"en","bound_author_id":991900002,"text":"John Stuart Mill examines when society and government may restrict a person''s freedom. He argues that preventing harm to others can justify intervention, while disagreement or disapproval alone cannot. The essay considers freedom of thought and discussion, individual ways of living, and the pressure exerted by public opinion. Rather than telling a fictional story, it develops an argument about the limits of authority and the value of allowing different views to be heard.","source_type":"official_catalog","source_name":"Project Gutenberg — original text","source_url":"https://www.gutenberg.org/cache/epub/34901/pg34901-images.html","evidence":[{"url":"https://www.gutenberg.org/cache/epub/34901/pg34901-images.html","checkedAt":"2026-11-07T16:54:59.393Z","facts":["Original English text, chapters on thought/discussion, individuality and limits of authority; not the generated catalogue blurb.","Edition ISBN and author independently bound through OL7925728M; no new language inference."]},{"url":"https://openlibrary.org/books/OL7925728M.json","checkedAt":"2026-11-07T16:54:59.393Z","facts":["Exact ISBN/title/language and bibliographic identity reviewed; synopsis is an original Work-level text, not an edition-language inference."]}],"provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-11-07T16:54:59.393Z","review_batch":"verified-synopses-20261107"}},{"relation":"catalog_work_descriptions","ref":"summary-3137","key":{"work_id":991880003,"language":"en"},"before":null,"after":{"work_id":991880003,"language":"en","bound_author_id":987339006,"text":"In 1946 Mississippi, respected farmer and war veteran Pete Banning kills a local minister, then refuses to explain why. His silence leaves his family, lawyers and neighbours struggling to understand an apparently senseless act. As the case moves through the courts, the novel turns back to Pete''s wartime experiences and the history of his family. The question of motive connects the public trial with events that those around him do not fully understand.","source_type":"official_publisher","source_name":"Penguin Random House","source_url":"https://www.penguinrandomhouse.com/books/586399/the-reckoning-by-john-grisham/","evidence":[{"url":"https://www.penguinrandomhouse.com/books/586399/the-reckoning-by-john-grisham/","checkedAt":"2026-11-07T16:54:59.393Z","facts":["Pete Banning, Clanton1946, killing and refusal to explain, court/family/WWII narrative verified by publisher.","Publisher international newsletter2020 explicitly pairs The Reckoning with ISBN9781984819956; adjacent A Time for Mercy text is not this ISBN."]},{"url":"https://openlibrary.org/books/OL35674672M.json","checkedAt":"2026-11-07T16:54:59.393Z","facts":["Exact ISBN/title/language and bibliographic identity reviewed; synopsis is an original Work-level text, not an edition-language inference."]}],"provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-11-07T16:54:59.393Z","review_batch":"verified-synopses-20261107"}},{"relation":"catalog_work_descriptions","ref":"summary-4182","key":{"work_id":991880004,"language":"en"},"before":null,"after":{"work_id":991880004,"language":"en","bound_author_id":991900004,"text":"Ravin and Khushi meet through a matrimonial website and begin getting to know one another at a distance. Calls and messages gradually turn an initial introduction into a relationship, and they start imagining a future together. Drawing on the author''s own experience, the novel follows the hopes and emotional vulnerability that accompany their plans. Their story confronts the possibility that a deeply felt love may not have the ending the couple expects.","source_type":"official_publisher","source_name":"Penguin Random House India","source_url":"https://www.penguin.co.in/book/i-too-had-a-love-story/","evidence":[{"url":"https://www.penguin.co.in/book/i-too-had-a-love-story/","checkedAt":"2026-11-07T16:54:59.393Z","facts":["Exact9780143418764, Ravinder Singh and English original verified.","Publisher names Ravin/Khushi, matrimonial website, true-life basis and relationship tested by loss; no ending disclosed."]},{"url":"https://openlibrary.org/books/OL36645820M.json","checkedAt":"2026-11-07T16:54:59.393Z","facts":["Exact ISBN/title/language and bibliographic identity reviewed; synopsis is an original Work-level text, not an edition-language inference."]}],"provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-11-07T16:54:59.393Z","review_batch":"verified-synopses-20261107"}},{"relation":"catalog_work_descriptions","ref":"summary-5226","key":{"work_id":991880005,"language":"nl"},"before":null,"after":{"work_id":991880005,"language":"nl","bound_author_id":991900005,"text":"Mirjam Blits vertelt hoe zij en haar man in februari 1943 worden opgepakt en hoe zij de Duitse concentratiekampen doorstaat. Na haar terugkeer in Amsterdam begint zij haar ervaringen op te schrijven, terwijl zij het verlies van haar man en familie onder ogen moet zien. Haar herinneringen gaan over geweld en ontbering, maar ook over de steun tussen meisjes en jonge vrouwen. Zo legt zij vast hoe zij elkaar tijdens de gevangenschap proberen overeind te houden.","source_type":"official_publisher","source_name":"Just Publishers","source_url":"https://justpublishers.nl/project/auschwitz-13917/","evidence":[{"url":"https://justpublishers.nl/project/auschwitz-13917/","checkedAt":"2026-11-07T16:54:59.393Z","facts":["Author, arrest25Feb1943 with husband, return Amsterdam and writing verified.","Female-prisoner solidarity and losses verified; no2020foreword facts transferred into2012edition."]},{"url":"https://openlibrary.org/books/OL43872702M.json","checkedAt":"2026-11-07T16:54:59.393Z","facts":["Exact ISBN/title/language and bibliographic identity reviewed; synopsis is an original Work-level text, not an edition-language inference."]}],"provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-11-07T16:54:59.393Z","review_batch":"verified-synopses-20261107"}},{"relation":"catalog_work_descriptions","ref":"summary-7315","key":{"work_id":991880006,"language":"en"},"before":null,"after":{"work_id":991880006,"language":"en","bound_author_id":991900006,"text":"Ronald M. Baecker examines how digital technologies influence everyday life and the institutions around us. The book considers computing in education, health, media, government and conflict, then weighs questions of privacy, security, inclusion and employment. Artificial intelligence is discussed alongside the choices people make about designing and using technology. The emphasis is on social and ethical consequences, helping readers consider both the benefits of computing and the problems it can create.","source_type":"official_publisher","source_name":"Oxford University Press","source_url":"https://academic.oup.com/book/41802","evidence":[{"url":"https://academic.oup.com/book/41802","checkedAt":"2026-11-07T16:54:59.393Z","facts":["Author/title and abstract scope verified with Oxford.","Exact paperback9780198827092 verified separately by Oxford India/CiNii; abstract hardcoverISBN is same underlying work, not a format correction."]},{"url":"https://openlibrary.org/books/OL28718461M.json","checkedAt":"2026-11-07T16:54:59.393Z","facts":["Exact ISBN/title/language and bibliographic identity reviewed; synopsis is an original Work-level text, not an edition-language inference."]}],"provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-11-07T16:54:59.393Z","review_batch":"verified-synopses-20261107"}},{"relation":"catalog_work_descriptions","ref":"summary-8359","key":{"work_id":991880008,"language":"en"},"before":null,"after":{"work_id":991880008,"language":"en","bound_author_id":991900008,"text":"Alice Miller argues that painful childhood experiences can continue to affect adult emotional and physical life. Drawing on personal histories and examples from writers'' lives, she examines the tension between remembered suffering and the expectation that children should honour or forgive their parents. The book presents Miller''s views on recognising earlier harm and listening to one''s feelings. She contrasts demands for family loyalty with the need to acknowledge a child''s experience.","source_type":"official_publisher","source_name":"W. W. Norton","source_url":"https://wwnorton.co.uk/books/9780393328639-the-body-never-lies","evidence":[{"url":"https://wwnorton.co.uk/books/9780393328639-the-body-never-lies","checkedAt":"2026-11-07T16:54:59.393Z","facts":["Alice Miller, English translation Andrew Jenkins and same work confirmed.","Childhood trauma, biographical examples and duty/forgiveness argument are attributed to author, not presented as established disease causation."]},{"url":"https://openlibrary.org/books/OL7452083M.json","checkedAt":"2026-11-07T16:54:59.393Z","facts":["Exact ISBN/title/language and bibliographic identity reviewed; synopsis is an original Work-level text, not an edition-language inference."]}],"provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-11-07T16:54:59.393Z","review_batch":"verified-synopses-20261107"}},{"relation":"catalog_work_descriptions","ref":"summary-8856","key":{"work_id":991880009,"language":"en"},"before":null,"after":{"work_id":991880009,"language":"en","bound_author_id":991900009,"text":"Ryū Murakami depicts a circle of young friends living in a Japanese town near an American military base. Drug use, sexual encounters and episodes of violence shape their routines and strain their connections with one another. The novel uses sharply focused physical sensations and fragmented experiences to portray their unstable world. Its subject is the destructive pattern of these lives and the difficulty of finding a lasting sense of connection.","source_type":"official_catalog","source_name":"Google Books / Kodansha bibliographic record","source_url":"https://books.google.com/books/about/Almost_Transparent_Blue.html?id=Qwc9zwEACAAJ","evidence":[{"url":"https://books.google.com/books/about/Almost_Transparent_Blue.html?id=Qwc9zwEACAAJ","checkedAt":"2026-11-07T16:54:59.393Z","facts":["Publisher-supplied catalogue description identifies same novel, young friends, military-base setting and destructive routines.","CiNiiBA61502662 binds exact2003English tradepaperback9784770029041, RyūMurakami/NancyAndrew; other1977ISBN is only narrative corroboration."]},{"url":"https://openlibrary.org/books/OL9037490M.json","checkedAt":"2026-11-07T16:54:59.393Z","facts":["Exact ISBN/title/language and bibliographic identity reviewed; synopsis is an original Work-level text, not an edition-language inference."]}],"provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-11-07T16:54:59.393Z","review_batch":"verified-synopses-20261107"}},{"relation":"catalog_work_descriptions","ref":"summary-9050","key":{"work_id":991880010,"language":"en"},"before":null,"after":{"work_id":991880010,"language":"en","bound_author_id":991900010,"text":"When Mark leaves Alexa to marry her best friend, her plans for the future collapse. His brother Scott Kelsey is concerned about the effect of the scandal on the family''s reputation. Alexa then marries Scott as a way of saving face, despite the hurt surrounding the arrangement. The story follows a relationship formed in the shadow of another man''s rejection, with family expectations and Alexa''s unresolved feelings at its centre.","source_type":"official_catalog","source_name":"South Dakota State Library — 1990 bibliography","source_url":"https://files.eric.ed.gov/fulltext/ED337172.pdf","evidence":[{"url":"https://files.eric.ed.gov/fulltext/ED337172.pdf","checkedAt":"2026-11-07T16:54:59.393Z","facts":["Library annotation PDFpage218 explicitly identifies SallyWentworth/Jilted and Alexa marryingScott afterMark marriesbestfriend.","ExactHarlequin1983paperback9780373106141 bound by OL10738224M; different largeprintedition is used only for shared plot, not edition facts."]},{"url":"https://openlibrary.org/books/OL10738224M.json","checkedAt":"2026-11-07T16:54:59.393Z","facts":["Exact ISBN/title/language and bibliographic identity reviewed; synopsis is an original Work-level text, not an edition-language inference."]}],"provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-11-07T16:54:59.393Z","review_batch":"verified-synopses-20261107"}},{"relation":"catalog_work_descriptions","ref":"summary-9404","key":{"work_id":991880011,"language":"en"},"before":null,"after":{"work_id":991880011,"language":"en","bound_author_id":991900011,"text":"After their father is murdered, the Locke children and their mother leave California for the family''s old house in Massachusetts. At Keyhouse, grief and a fresh start become entangled with doors and keys that have extraordinary powers. The youngest child begins discovering what those powers can do, while a dangerous presence has its own interest in the house. This opening graphic-novel volume introduces the family and the mysteries surrounding their inheritance.","source_type":"official_publisher","source_name":"Subterranean Press — same graphic novel","source_url":"https://subterraneanpress.com/locke-key-welcome-to-lovecraft/","evidence":[{"url":"https://subterraneanpress.com/locke-key-welcome-to-lovecraft/","checkedAt":"2026-11-07T16:54:59.393Z","facts":["Same WelcomeToLovecraft graphic-novel story by JoeHill/GabrielRodriguez, not TV adaptation.","OriginalIDW9781600102370 exactISBN verified by PublishersWeekly and OL; SubPressscript extras/ISBN not imported as originaledition facts."]},{"url":"https://openlibrary.org/books/OL23106590M.json","checkedAt":"2026-11-07T16:54:59.393Z","facts":["Exact ISBN/title/language and bibliographic identity reviewed; synopsis is an original Work-level text, not an edition-language inference."]}],"provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-11-07T16:54:59.393Z","review_batch":"verified-synopses-20261107"}}],"bindings":[{"work":{"id":991880002,"title":"On Liberty","author_id":991900002,"first_publish_year":1859,"open_library_id":"OL1068091W","cover_id":null,"source_type":"open_library","work_type":null,"native_identity_key":null},"author":{"id":991900002,"name":"John Stuart Mill","open_library_id":"OL108289A"}},{"work":{"id":991880003,"title":"The Reckoning","author_id":987339006,"first_publish_year":2018,"open_library_id":"OL17930238W","cover_id":null,"source_type":null,"work_type":null,"native_identity_key":null},"author":{"id":987339006,"name":"John Grisham","open_library_id":"OL39329A"}},{"work":{"id":991880004,"title":"I Too Had a Love Story","author_id":991900004,"first_publish_year":2009,"open_library_id":"OL16793664W","cover_id":null,"source_type":null,"work_type":null,"native_identity_key":null},"author":{"id":991900004,"name":"Ravinder Singh","open_library_id":"OL7107008A"}},{"work":{"id":991880005,"title":"Auschwitz 13917","author_id":991900005,"first_publish_year":1961,"open_library_id":"OL7358314W","cover_id":null,"source_type":null,"work_type":null,"native_identity_key":null},"author":{"id":991900005,"name":"Mirjam Blits","open_library_id":"OL2184754A"}},{"work":{"id":991880006,"title":"Computers and Society","author_id":991900006,"first_publish_year":2019,"open_library_id":"OL21206512W","cover_id":null,"source_type":null,"work_type":null,"native_identity_key":null},"author":{"id":991900006,"name":"Ronald M. Baecker","open_library_id":"OL1008943A"}},{"work":{"id":991880008,"title":"The Body Never Lies","author_id":991900008,"first_publish_year":2005,"open_library_id":"OL1873221W","cover_id":null,"source_type":null,"work_type":null,"native_identity_key":null},"author":{"id":991900008,"name":"Alice Miller","open_library_id":"OL224269A"}},{"work":{"id":991880009,"title":"Almost Transparent Blue","author_id":991900009,"first_publish_year":2003,"open_library_id":"OL7989537W","cover_id":null,"source_type":null,"work_type":null,"native_identity_key":null},"author":{"id":991900009,"name":"Ryū Murakami","open_library_id":"OL656644A"}},{"work":{"id":991880010,"title":"Jilted","author_id":991900010,"first_publish_year":1983,"open_library_id":"OL3770495W","cover_id":null,"source_type":null,"work_type":null,"native_identity_key":null},"author":{"id":991900010,"name":"Sally Wentworth","open_library_id":"OL664669A"}},{"work":{"id":991880011,"title":"Locke & Key, Vol. 1","author_id":991900011,"first_publish_year":2008,"open_library_id":"OL13453816W","cover_id":null,"source_type":null,"work_type":null,"native_identity_key":null},"author":{"id":991900011,"name":"Joe Hill","open_library_id":"OL2631898A"}}],"authorCorpora":[]}'::jsonb;a jsonb;b jsonb;actual jsonb;oldrow jsonb;nextrow jsonb;k jsonb;kv record;ids jsonb:='{}';cols text;vals text;predicate text;v_id bigint;i integer:=0;n integer;begin
 for b in select value from jsonb_array_elements(payload->'bindings') loop
  select to_jsonb(w) into actual from public.works w where id=(b->'work'->>'id')::bigint;
  if actual is distinct from b->'work' and not exists(select 1 from jsonb_array_elements(payload->'actions') p where p->>'relation'='works' and p->'key'=jsonb_build_object('id',(b->'work'->>'id')::bigint) and actual=p->'after') then raise exception 'Work preflight drift';end if;
  select to_jsonb(t) into actual from public.authors t where id=(b->'author'->>'id')::bigint;
  if actual is distinct from b->'author' then raise exception 'Author preflight drift';end if;
 end loop;
 for b in select value from jsonb_array_elements(payload->'authorCorpora') loop
  select coalesce(jsonb_agg(to_jsonb(w) order by id),'[]') into actual from public.works w where author_id=(b->>'author_id')::bigint and not exists(select 1 from jsonb_array_elements(payload->'actions') p where p->>'relation'='works' and p->'before'='null' and w.native_identity_key=p->'after'->>'native_identity_key');
  select coalesce(jsonb_agg(to_jsonb(jsonb_populate_record(null::public.works,value)) order by (value->>'id')::bigint),'[]') into oldrow from jsonb_array_elements(b->'rows');
  select coalesce(jsonb_agg(to_jsonb(jsonb_populate_record(null::public.works,coalesce((select p->'after' from jsonb_array_elements(payload->'actions') p where p->>'relation'='works' and p->'before'<>'null' and p->'key'=jsonb_build_object('id',(v.value->>'id')::bigint)),v.value))) order by (v.value->>'id')::bigint),'[]') into nextrow from jsonb_array_elements(b->'rows') v;
  if actual is distinct from oldrow and actual is distinct from nextrow then raise exception 'New Work author corpus drift; repeat identity review';end if;
 end loop;
 for a in select value from jsonb_array_elements(payload->'actions') loop
  i:=i+1;k:=a->'key';nextrow:=a->'after';oldrow:=a->'before';
  if a->>'relation' not in ('authors','works','editions','catalog_work_descriptions','catalog_edition_metadata') then raise exception 'Unreviewed relation';end if;
  for kv in select * from jsonb_each(nextrow) loop
   if jsonb_typeof(kv.value)='string' and left(kv.value#>>'{}',1)='@' then
    if not ids ? substring(kv.value#>>'{}',2) then raise exception 'Unresolved parent reference';end if;
    nextrow:=jsonb_set(nextrow,array[kv.key],ids->substring(kv.value#>>'{}',2));
   end if;
  end loop;
  for kv in select * from jsonb_each(k) loop
   if jsonb_typeof(kv.value)='string' and left(kv.value#>>'{}',1)='@' then k:=jsonb_set(k,array[kv.key],ids->substring(kv.value#>>'{}',2));end if;
  end loop;
  if exists(select 1 from jsonb_each(k) where value='null'::jsonb) then raise exception 'Unresolved/null identity key';end if;
  -- Typed equality uses the existing primary/natural-key index. Keep full-row
  -- JSON comparison below; only candidate lookup changes, not CAS protection.
  select string_agg(format('t.%I=(jsonb_populate_record(null::public.%I,$1)).%I',key,a->>'relation',key),' and ' order by key) into predicate from jsonb_each(k);
  execute format('select to_jsonb(t) from public.%I t where %s for update',a->>'relation',predicate) into actual using k;
  if oldrow<>'null'::jsonb then
   execute format('select to_jsonb(jsonb_populate_record(null::public.%I,$1))',a->>'relation') into oldrow using oldrow;
   execute format('select to_jsonb(jsonb_populate_record(null::public.%I,$1))',a->>'relation') into nextrow using nextrow;
   if actual is not distinct from nextrow then continue;end if;
   if actual is distinct from oldrow then raise exception 'Changed existing row in % at action %',a->>'relation',i;end if;
   select string_agg(format('%I=(jsonb_populate_record(null::public.%I,$1)).%I',key,a->>'relation',key),',') into cols from jsonb_each(nextrow) where value is distinct from oldrow->key;
   execute format('update public.%I t set %s where %s returning to_jsonb(t)',a->>'relation',cols,replace(predicate,'$1','$2')) into actual using nextrow,k;
   insert into catalog_release_receipt values(i,a->>'relation',k,oldrow,actual);
  elsif actual is not null then
   if a->>'relation' in ('catalog_work_descriptions','catalog_edition_metadata') then
    execute format('select to_jsonb(jsonb_populate_record(null::public.%I,$1))',a->>'relation') into nextrow using nextrow;
    if actual is distinct from nextrow then raise exception 'Existing reviewed presentation differs; never overwrite';end if;
   elsif not actual @> nextrow then raise exception 'Existing natural identity differs';end if;
  else
   if a->>'relation'='editions' and exists(select 1 from public.editions e where (nextrow->>'isbn_13' is not null and regexp_replace(coalesce(e.isbn_13,''),'[-[:space:]]','','g')=nextrow->>'isbn_13') or (nextrow->>'isbn_10' is not null and upper(regexp_replace(coalesce(e.isbn_10,''),'[-[:space:]]','','g'))=nextrow->>'isbn_10') or (nextrow->>'open_library_edition_id' is not null and e.open_library_edition_id=nextrow->>'open_library_edition_id')) then raise exception 'Global edition identity collision';end if;
   select string_agg(format('%I',key),',' order by key),string_agg(format('(jsonb_populate_record(null::public.%I,$1)).%I',a->>'relation',key),',' order by key) into cols,vals from jsonb_each(nextrow);
   execute format('insert into public.%I(%s) select %s returning to_jsonb(%I)',a->>'relation',cols,vals,a->>'relation') into actual using nextrow;
   insert into catalog_release_receipt values(i,a->>'relation',k,null,actual);
  end if;
  if actual ? 'id' then ids:=jsonb_set(ids,array[a->>'ref'],actual->'id');end if;
 end loop;
 select count(*) into n from catalog_release_receipt;
